// Positional arrays make each topic's visual and practice contract concise;
// consumers receive a fully named, topic-specific blueprint object.
function plan(title, level, summary, prerequisites, outcomes, sequence, visual, practice, misconceptions, sources, depth, reviewFocus) {
  return { title, level, blueprint: { summary, outcomes, prerequisites, sequence,
    visual: { type: visual[0], question: visual[1], interaction: visual[2] },
    practice: { task: practice[0], success: practice[1] }, misconceptions, sources, depth, reviewFocus } };
}
